{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "The closest analogue (Morgan 0.6441), an ivabradine-type benzazepinone with the same lactam-N-propyl-N-methyl-CH2-aryl scaffold, had an absolute oral bioavailability of 51.5 ± 17.8% (range 29–80%) in healthy volunteers after a 7.5 mg oral solution vs IV, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Ivabradine, a close structural relative of the query, has an oral bioavailability close to 40% in healthy volunteers despite near-complete absorption and hepatic first-pass metabolism, indicating that this dimethoxyaryl/amine/lactam scaffold can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine, a lower-similarity dimethoxybenzoquinolizine ketone (Morgan 0.373), had a mean oral F of only 4.9% in patients, but its ketone carbonyl and different fused-ring scaffold limit transferability to the query's amide/amine system.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, a dimethoxy-tetrahydroisoquinoline amide/amine, had an absolute F of 11.2% in healthy subjects, but its low Morgan similarity (0.247) and different overall topology weaken its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a close structural analogue of an ivabradine-type benzazepinone (Morgan 0.6441) with human absolute F of 45–51.5%, well above the 20% threshold. Lower-similarity low-F compounds such as tetrabenazine and almorexant are less transferable because of ketone/prodrug or different scaffolds. Therefore F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability data exist for the exact query molecule.",
    "The closest analogue differs in lactam ring size (isoquinolinone vs benzazepinone) and aryl group (dimethoxyindane vs dimethoxyphenethyl), which could alter first-pass metabolism.",
    "No permeability or metabolic stability data are available for the query.",
    "One tetrabenazine record (C47) reports ≥75% F, conflicting with the majority low-F data and adding uncertainty to that family."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C53", "C48", "C46"],
      "decision_effect": "changed",
      "direction": "supportive",
      "family": "ivabradine/benzazepinone"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C56", "C51", "C55", "C47", "C52"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "tetrabenazine"
    },
    {
      "applicability": "low",
      "card_ids": ["C49", "C50"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "armepavine"
    },
    {
      "applicability": "low",
      "card_ids": ["C54", "C45"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "carmegliptin"
    }
  ],
  "revision_action": "flip"
}

